"use strict";
// The `dcmnorm` package entry point: everything the native addon exports (index.js, generated by
// napi-rs), plus the typed dataset API of #6 - read / toDicomJson / write / renderPixels /
// transcodeTo, `DicomDataset`, typed errors, and the generated Tag / VR / TransferSyntax /
// SOPClassUID constants (dicom-constants.js). The dataset functions wrap the addon's `dataset*`
// internals; see README.md "Typed datasets".

const native = require("./index.js");
const constants = require("./dicom-constants.js");

const { VR_KIND, TRANSFER_SYNTAX_INFO, SOP_CLASS_NAMES } = constants;

// ---------------------------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------------------------

/** Every dataset API failure. `kind` is the native classification; `code` is `ERR_DCMNORM_<KIND>`. */
class DcmnormError extends Error {
  constructor(message, info = {}) {
    super(message);
    this.name = new.target.name;
    this.kind = info.kind || "Other";
    this.code = "ERR_DCMNORM_" + this.kind.replace(/([a-z])([A-Z])/g, "$1_$2").toUpperCase();
    this.sourceTransferSyntaxUid = info.sourceTransferSyntaxUid ?? null;
    this.targetTransferSyntaxUid = info.targetTransferSyntaxUid ?? null;
    this.frameIndex = info.frameIndex ?? null;
  }
}
class InvalidDicomError extends DcmnormError {}
class UnsupportedTransferSyntaxError extends DcmnormError {}
class DecodeError extends DcmnormError {}
class EncodeError extends DcmnormError {}
class RenderError extends DcmnormError {}
class DimseError extends DcmnormError {}

const ERROR_CLASSES = {
  InvalidDicom: InvalidDicomError,
  UnsupportedTransferSyntax: UnsupportedTransferSyntaxError,
  Decode: DecodeError,
  Encode: EncodeError,
  Render: RenderError,
  Dimse: DimseError,
};

function unwrap(result) {
  if (result.error) {
    const ErrorClass = ERROR_CLASSES[result.error.kind] || DcmnormError;
    throw new ErrorClass(result.error.message, result.error);
  }
  return result;
}

// ---------------------------------------------------------------------------------------------
// Sources
// ---------------------------------------------------------------------------------------------

function isBytes(value) {
  return Buffer.isBuffer(value) || value instanceof Uint8Array;
}

/**
 * A source as [path, bytes]: a path string, a Buffer / Uint8Array, or a readable stream / async
 * iterable of chunks (collected into one Buffer: the native reader needs the bytes).
 */
async function sourceArgs(source) {
  if (typeof source === "string") return [source, null];
  if (source instanceof URL) return [require("url").fileURLToPath(source), null];
  if (isBytes(source)) return [null, Buffer.isBuffer(source) ? source : Buffer.from(source.buffer, source.byteOffset, source.byteLength)];
  if (source && typeof source[Symbol.asyncIterator] === "function") {
    const chunks = [];
    for await (const chunk of source) chunks.push(typeof chunk === "string" ? Buffer.from(chunk) : Buffer.from(chunk));
    return [null, Buffer.concat(chunks)];
  }
  throw new TypeError("a DICOM source is a path, a Buffer/Uint8Array or a readable stream");
}

// ---------------------------------------------------------------------------------------------
// The binary data set form (src/dicom_io/dataset_tree.rs: encode_document / decode_document)
// ---------------------------------------------------------------------------------------------

const KIND_NAMES = ["empty", "strings", "ints", "doubles", "tags", "bytes", "bulkData", "fragments", "sequence"];

function decodeDocument(buffer, source) {
  let pos = 0;
  const u8 = () => buffer[pos++];
  const u32 = () => {
    const v = buffer.readUInt32BE(pos);
    pos += 4;
    return v;
  };
  const str = () => {
    const n = u32();
    const s = buffer.toString("utf8", pos, pos + n);
    pos += n;
    return s;
  };
  const take = (n) => {
    const b = Buffer.from(buffer.subarray(pos, pos + n));
    pos += n;
    return b;
  };
  const tree = () => {
    const count = u32();
    const elements = new Map();
    for (let i = 0; i < count; i++) {
      const tag = u32();
      const vr = String.fromCharCode(u8(), u8());
      const kind = u8();
      let value;
      switch (kind) {
        case 0: value = null; break;
        case 1: { const n = u32(); value = []; for (let j = 0; j < n; j++) value.push(str()); break; }
        case 2: { const n = u32(); value = []; for (let j = 0; j < n; j++) { value.push(Number(buffer.readBigInt64BE(pos))); pos += 8; } break; }
        case 3: { const n = u32(); value = []; for (let j = 0; j < n; j++) { value.push(buffer.readDoubleBE(pos)); pos += 8; } break; }
        case 4: { const n = u32(); value = []; for (let j = 0; j < n; j++) value.push(u32()); break; }
        case 5: value = take(u32()); break;
        case 6: {
          const offset = Number(buffer.readBigUInt64BE(pos));
          const length = Number(buffer.readBigInt64BE(pos + 8));
          pos += 16;
          value = Object.freeze({ tag, vr, offset, length });
          break;
        }
        case 7: {
          const n = u32();
          const offsetTable = [];
          for (let j = 0; j < n; j++) offsetTable.push(u32());
          const m = u32();
          const fragments = [];
          for (let j = 0; j < m; j++) fragments.push(take(u32()));
          value = { offsetTable, fragments };
          break;
        }
        case 8: { const n = u32(); value = []; for (let j = 0; j < n; j++) value.push(new DicomDataset(tree())); break; }
        default: throw new Error(`unknown value kind ${kind} in the binary data set`);
      }
      elements.set(tag, Object.freeze({ tag, vr, type: KIND_NAMES[kind], value }));
    }
    return elements;
  };
  if (buffer.toString("latin1", 0, 4) !== "DCMT" || buffer[4] !== 1) throw new Error("not a binary data set");
  pos = 5;
  const transferSyntaxUid = str();
  const meta = tree();
  const dataset = tree();
  return new DicomDataset(dataset, { fileMeta: new DicomDataset(meta), transferSyntaxUid: transferSyntaxUid || null, source });
}

function encodeDocument(dataset) {
  const parts = [];
  const u32 = (v) => { const b = Buffer.alloc(4); b.writeUInt32BE(v >>> 0); parts.push(b); };
  const str = (s) => { const b = Buffer.from(s, "utf8"); u32(b.length); parts.push(b); };
  const tree = (ds) => {
    u32(ds.size);
    for (const e of ds) {
      u32(e.tag);
      parts.push(Buffer.from(e.vr, "latin1"));
      const kind = KIND_NAMES.indexOf(e.type);
      parts.push(Buffer.from([kind]));
      const v = e.value;
      switch (e.type) {
        case "empty": break;
        case "strings": u32(v.length); v.forEach(str); break;
        case "ints": { u32(v.length); const b = Buffer.alloc(8 * v.length); v.forEach((x, i) => b.writeBigInt64BE(BigInt(Math.trunc(x)), 8 * i)); parts.push(b); break; }
        case "doubles": { u32(v.length); const b = Buffer.alloc(8 * v.length); v.forEach((x, i) => b.writeDoubleBE(x, 8 * i)); parts.push(b); break; }
        case "tags": u32(v.length); v.forEach(u32); break;
        case "bytes": u32(v.length); parts.push(Buffer.from(v)); break;
        case "bulkData": { const b = Buffer.alloc(16); b.writeBigUInt64BE(BigInt(v.offset)); b.writeBigInt64BE(BigInt(v.length), 8); parts.push(b); break; }
        case "fragments": u32(v.offsetTable.length); v.offsetTable.forEach(u32); u32(v.fragments.length); v.fragments.forEach((f) => { u32(f.length); parts.push(Buffer.from(f)); }); break;
        case "sequence": u32(v.length); v.forEach(tree); break;
        default: throw new Error(`unknown value type ${e.type}`);
      }
    }
  };
  parts.push(Buffer.from("DCMT", "latin1"), Buffer.from([1]));
  str(dataset.transferSyntaxUid || "");
  tree(dataset.fileMeta);
  tree(dataset);
  return Buffer.concat(parts);
}

// ---------------------------------------------------------------------------------------------
// DicomDataset
// ---------------------------------------------------------------------------------------------

function hex8(tag) {
  return (tag >>> 0).toString(16).toUpperCase().padStart(8, "0");
}

function formatNumber(v) {
  return Number.isInteger(v) ? String(v) : String(v);
}

function parseNumber(text) {
  const v = Number(String(text).trim());
  return Number.isNaN(v) ? undefined : v;
}

/** A PN value split into groups (alphabetic, ideographic, phonetic) and components. */
class PersonName {
  constructor(value) {
    this.value = value || "";
    const groups = this.value.split("=");
    const group = (text = "") => {
      const c = text.split("^");
      return Object.freeze({
        familyName: c[0] || "",
        givenName: c[1] || "",
        middleName: c[2] || "",
        namePrefix: c[3] || "",
        nameSuffix: c.slice(4).join("^"),
      });
    };
    this.alphabetic = group(groups[0]);
    this.ideographic = group(groups[1]);
    this.phonetic = group(groups[2]);
    Object.freeze(this);
  }
  get familyName() { return this.alphabetic.familyName; }
  get givenName() { return this.alphabetic.givenName; }
  toString() { return this.value; }
}

/**
 * A read-only DICOM data set as plain JS values. Iterates its elements `{ tag, vr, type, value }`
 * in ascending tag order; `type` is how the value is held: `strings` (text VRs, one string per
 * value), `ints` (numbers; SV/UV beyond 2^53 lose precision), `doubles`, `tags`, `bytes`
 * (Buffer), `bulkData` (`{ tag, vr, offset, length }`, left in the source), `fragments`,
 * `sequence` (DicomDataset items) or `empty`.
 */
class DicomDataset {
  constructor(elements = new Map(), { fileMeta = null, transferSyntaxUid = null, source = null } = {}) {
    this._elements = new Map([...elements.entries()].sort((a, b) => (a[0] >>> 0) - (b[0] >>> 0)));
    this._fileMeta = fileMeta;
    this.transferSyntaxUid = transferSyntaxUid;
    this._source = source;
    Object.freeze(this);
  }

  static empty() { return new DicomDataset(); }

  get size() { return this._elements.size; }
  [Symbol.iterator]() { return this._elements.values(); }
  tags() { return [...this._elements.keys()]; }
  has(tag) { return this._elements.has(tag); }
  get(tag) { return this._elements.get(tag); }
  vr(tag) { const e = this._elements.get(tag); return e ? e.vr : null; }

  /** The File Meta Information read with the data set (not written back; `write` creates it). */
  get fileMeta() { return this._fileMeta || EMPTY; }
  get transferSyntax() { return TRANSFER_SYNTAX_INFO[this.transferSyntaxUid] || null; }

  /** Value `index` as text, or `defaultValue` if absent or empty. */
  getString(tag, defaultValue = null, index = 0) {
    const e = this._elements.get(tag);
    if (!e || !Array.isArray(e.value) || index >= e.value.length) return defaultValue;
    const v = e.value[index];
    switch (e.type) {
      case "strings": return v === "" ? defaultValue : v;
      case "ints": case "doubles": return formatNumber(v);
      case "tags": return hex8(v);
      default: return defaultValue;
    }
  }

  /** Every value as text; null if absent. */
  getStrings(tag) {
    const e = this._elements.get(tag);
    if (!e) return null;
    switch (e.type) {
      case "strings": return [...e.value];
      case "ints": case "doubles": return e.value.map(formatNumber);
      case "tags": return e.value.map(hex8);
      default: return [];
    }
  }

  /** Value `index` as a number (IS/DS parsed), or `defaultValue`. */
  getNumber(tag, defaultValue = null, index = 0) {
    const e = this._elements.get(tag);
    if (!e || !Array.isArray(e.value) || index >= e.value.length) return defaultValue;
    if (e.type === "strings") {
      const v = parseNumber(e.value[index]);
      return v === undefined || e.value[index] === "" ? defaultValue : v;
    }
    return e.type === "ints" || e.type === "doubles" || e.type === "tags" ? e.value[index] : defaultValue;
  }

  /** dcm4che-style: an integer (IS parsed; DS truncated). */
  getInt(tag, defaultValue = null, index = 0) {
    const v = this.getNumber(tag, null, index);
    return v === null ? defaultValue : Math.trunc(v);
  }

  getFloat(tag, defaultValue = null, index = 0) {
    return this.getNumber(tag, defaultValue, index);
  }

  /** Every value as a number; null if absent (throws on an unparseable value). */
  getNumbers(tag) {
    const e = this._elements.get(tag);
    if (!e) return null;
    if (e.type === "strings") {
      return e.value.map((s) => {
        const v = parseNumber(s);
        if (v === undefined) throw new TypeError(`'${s}' is not a number`);
        return v;
      });
    }
    return e.type === "ints" || e.type === "doubles" || e.type === "tags" ? [...e.value] : [];
  }

  getInts(tag) { const v = this.getNumbers(tag); return v && v.map(Math.trunc); }
  getFloats(tag) { return this.getNumbers(tag); }

  /** A binary value that was read (a copy), or null (absent, or left in the source). */
  getBytes(tag) {
    const e = this._elements.get(tag);
    if (!e) return null;
    if (e.type === "bytes") return Buffer.from(e.value);
    if (e.type === "empty") return Buffer.alloc(0);
    return null;
  }

  getBulkDataRef(tag) { const e = this._elements.get(tag); return e && e.type === "bulkData" ? e.value : null; }
  getSequence(tag) { const e = this._elements.get(tag); return e && e.type === "sequence" ? [...e.value] : null; }
  getNestedDataset(tag, index = 0) { const s = this.getSequence(tag); return s && index < s.length ? s[index] : null; }
  getPersonName(tag, index = 0) { const v = this.getString(tag, null, index); return v === null ? null : new PersonName(v); }

  get numberOfFrames() { return Math.max(1, this.getInt(constants.Tag.NumberOfFrames, 1)); }
  get frameTimeMillis() { return this.getNumber(constants.Tag.FrameTime, null); }
  get frameTimeVector() { return this.has(constants.Tag.FrameTimeVector) ? this.getNumbers(constants.Tag.FrameTimeVector) : null; }

  /** Vertical / horizontal pixel size: PixelAspectRatio, else the PixelSpacing ratio, else 1. */
  get pixelAspectRatio() {
    for (const tag of [constants.Tag.PixelAspectRatio, constants.Tag.PixelSpacing]) {
      const v = this.has(tag) ? this.getNumbers(tag) : null;
      if (v && v.length === 2 && v[0] > 0 && v[1] > 0) return v[0] / v[1];
    }
    return 1;
  }

  toBuilder() { return new DicomDatasetBuilder(this); }
}

const EMPTY = new DicomDataset();

/** Builds a modified copy of a DicomDataset; bulk data references stay references. */
class DicomDatasetBuilder {
  constructor(from) {
    this._elements = new Map(from._elements);
    this._fileMeta = from._fileMeta;
    this._transferSyntaxUid = from.transferSyntaxUid;
    this._source = from._source;
  }

  _put(tag, vr, type, value) {
    if (tag >>> 16 === 0x0002) throw new Error("File Meta Information is created by write(), not set in the data set");
    this._elements.set(tag, Object.freeze({ tag, vr, type, value }));
    return this;
  }

  _vr(tag) {
    const vr = native.vrOf(tag);
    if (!vr) throw new Error(`${hex8(tag)} is not in the dictionary: give its VR`);
    return vr;
  }

  /** Text values for any VR (a binary VR parses them when written): `set(tag, vr, ...values)`,
   * or `set(tag, [values])` with the dictionary VR. */
  set(tag, vr, ...values) {
    if (Array.isArray(vr)) return this.set(tag, this._vr(tag), ...vr);
    if (!(vr in VR_KIND)) throw new TypeError(`unknown VR ${vr}: set(tag, vr, ...values) or set(tag, [values])`);
    if (vr === "SQ") throw new Error("use setSequence for SQ");
    return values.length === 0 ? this._put(tag, vr, "empty", null) : this._put(tag, vr, "strings", values.map((v) => (v == null ? "" : String(v))));
  }
  setInt(tag, vr, ...values) { return this._put(tag, vr, values.length ? "ints" : "empty", values.length ? values.map(Math.trunc) : null); }
  setDouble(tag, vr, ...values) { return this._put(tag, vr, values.length ? "doubles" : "empty", values.length ? [...values] : null); }
  setTags(tag, ...tags) { return this._put(tag, "AT", tags.length ? "tags" : "empty", tags.length ? tags.map((t) => t >>> 0) : null); }
  setBytes(tag, vr, bytes) { return this._put(tag, vr, bytes.length ? "bytes" : "empty", bytes.length ? Buffer.from(bytes) : null); }
  setNull(tag, vr) { return this._put(tag, vr, "empty", null); }
  setSequence(tag, items) { return this._put(tag, "SQ", "sequence", Object.freeze([...items])); }
  addSequenceItem(tag, item) {
    const e = this._elements.get(tag);
    return this.setSequence(tag, [...(e && e.type === "sequence" ? e.value : []), item]);
  }
  editSequenceItem(tag, index, edit) {
    const e = this._elements.get(tag);
    if (!e || e.type !== "sequence" || index < 0 || index >= e.value.length) throw new RangeError(`${hex8(tag)} has no item ${index}`);
    const builder = e.value[index].toBuilder();
    edit(builder);
    const items = [...e.value];
    items[index] = builder.build();
    return this.setSequence(tag, items);
  }
  removeSequenceItem(tag, index) {
    const e = this._elements.get(tag);
    if (!e || e.type !== "sequence" || index < 0 || index >= e.value.length) throw new RangeError(`${hex8(tag)} has no item ${index}`);
    return this.setSequence(tag, e.value.filter((_, i) => i !== index));
  }
  remove(tag) { this._elements.delete(tag); return this; }
  removePrivateTags() { for (const tag of [...this._elements.keys()]) if ((tag >>> 16) & 1) this._elements.delete(tag); return this; }
  build() {
    return new DicomDataset(this._elements, { fileMeta: this._fileMeta, transferSyntaxUid: this._transferSyntaxUid, source: this._source });
  }
}

// ---------------------------------------------------------------------------------------------
// The API
// ---------------------------------------------------------------------------------------------

/**
 * Read a DICOM object into a DicomDataset. `source`: a path, a Buffer/Uint8Array, or a readable
 * stream (collected first). Options: `untilPixelData` (stop at the PixelData header),
 * `loadBulkData` (read bulk values instead of leaving them as references).
 */
async function read(source, options = {}) {
  const [path, bytes] = await sourceArgs(source);
  const result = unwrap(await native.datasetRead(path, bytes, !!options.untilPixelData, !!options.loadBulkData));
  return decodeDocument(result.data, path !== null ? { path } : { bytes });
}

const PLACEHOLDER = /"dcmnorm-bulk:([0-9A-F]{8}):([A-Z]{2}):(\d+):(-?\d+)"/g;

function jsonOptions(options) {
  return {
    includeTags: options.includeTags,
    excludeTags: options.excludeTags,
    bulkData: options.bulkData,
    bulkDataUriBase: options.bulkDataUriBase,
    includeFileMeta: options.includeFileMeta,
    keywordAndVm: options.keywordAndVM,
    placeholderUris: typeof options.bulkDataUriBuilder === "function",
  };
}

function applyUriBuilder(json, builder) {
  if (typeof builder !== "function") return json;
  return json.replace(PLACEHOLDER, (_, tag, vr, offset, length) => {
    const uri = builder(Object.freeze({ tag: parseInt(tag, 16), vr, offset: Number(offset), length: Number(length) }));
    if (typeof uri !== "string") throw new TypeError("bulkDataUriBuilder must return a string");
    return JSON.stringify(uri);
  });
}

/**
 * PS3.18 Annex F DICOM JSON of a source or a DicomDataset, as a string. Options: `includeTags`,
 * `excludeTags`, `bulkData` ('uri' default | 'inline'), `bulkDataUriBase`,
 * `bulkDataUriBuilder(ref) => string`, `includeFileMeta`, `keywordAndVM`.
 */
async function toDicomJson(source, options = {}) {
  let result;
  if (source instanceof DicomDataset) {
    const s = source._source || {};
    result = unwrap(await native.datasetDocumentToJson(encodeDocument(source), s.path ?? null, s.bytes ?? null, jsonOptions(options)));
  } else {
    const [path, bytes] = await sourceArgs(source);
    result = unwrap(await native.datasetSourceToJson(path, bytes, jsonOptions(options)));
  }
  return applyUriBuilder(result.text, options.bulkDataUriBuilder);
}

/**
 * Write a DicomDataset as a DICOM file to `outputPath`, or (outputPath null) resolve to its bytes.
 * File Meta Information is created for it; bulk data references are read natively from the source
 * it was read from (or `options.bulkDataSource`: a path or Buffer). `options.transferSyntax`
 * transcodes.
 */
async function write(dataset, outputPath = null, options = {}) {
  let s = dataset._source || {};
  if (options.bulkDataSource !== undefined) {
    s = typeof options.bulkDataSource === "string" ? { path: options.bulkDataSource } : { bytes: Buffer.from(options.bulkDataSource) };
  }
  const result = unwrap(
    await native.datasetWrite(encodeDocument(dataset), s.path ?? null, s.bytes ?? null, outputPath, options.transferSyntax ?? null),
  );
  return outputPath === null ? result.data : undefined;
}

/** `write(dataset, null, options)`: the file's bytes. */
function toBuffer(dataset, options = {}) {
  return write(dataset, null, options);
}

/**
 * Render frame `frameIndex` to 8-bit display pixels - no image encoding: resolves to
 * `{ width, height, channels, pixels, overlays, selectedOverlayIndex }`, `pixels` a Buffer of
 * `width * height * channels` bytes (1 channel gray, 3 RGB interleaved), rows top to bottom.
 * Params: `windowCenter`/`windowWidth`, `voiLut`, `modalityLut`, `iccProfile`, `outputWidth`,
 * `outputHeight`, `showOverlays`, `overlayIndex`, `overlayColor`.
 */
async function renderPixels(source, frameIndex = 0, params = {}) {
  const [path, bytes] = await sourceArgs(source);
  const result = unwrap(await native.datasetRenderPixels(path, bytes, frameIndex, params));
  return result.rendered;
}

/** Transcode a source to `transferSyntaxUid`: to `outputPath`, or (null) resolve to the bytes. */
async function transcodeTo(source, transferSyntaxUid, outputPath = null) {
  const [path, bytes] = await sourceArgs(source);
  const result = unwrap(await native.datasetTranscode(path, bytes, outputPath, transferSyntaxUid));
  return outputPath === null ? result.data : undefined;
}

module.exports = {
  ...native,
  ...constants,
  DcmnormError,
  InvalidDicomError,
  UnsupportedTransferSyntaxError,
  DecodeError,
  EncodeError,
  RenderError,
  DimseError,
  DicomDataset,
  DicomDatasetBuilder,
  PersonName,
  read,
  toDicomJson,
  write,
  toBuffer,
  renderPixels,
  transcodeTo,
  sopClassName: (uid) => SOP_CLASS_NAMES[uid] ?? null,
};
